INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Teste ich hier nur das Gesamtsystem?', 2, '[{"text": "Nein", "correct": true, "because": "Abgestufte Testphasen"}, {"text": "Ja", "correct": false, "because": "Mehrere Ebenen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Testebene prüft einzelne Komponenten?', 3, '[{"text": "Unit-Tests", "correct": true, "because": "Einzelmodule testen"}, {"text": "Integrationstests", "correct": false, "because": "Zusammenwirken prüfen"}, {"text": "Systemtests", "correct": false, "because": "Gesamtsystem testen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Testphasen gehören zum V-Modell?', 5, '[{"text": "Unit-Tests", "correct": true, "because": "Kleinste Einheiten prüfen"}, {"text": "Integrationstests", "correct": true, "because": "Komponenten verbinden"}, {"text": "Zufällige Tests", "correct": false, "because": "Strukturierte Phasen"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Systemtests prüfen das Gesamtsystem. b) Unit-Tests sind optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Unit-Tests essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei diesen Testebenen?', 4, '[{"text": "Unit-Tests", "correct": false, "because": "Kleinste Einheiten prüfen"}, {"text": "Integrationstests", "correct": false, "because": "Zusammenwirken sicherstellen"}, {"text": "Unstrukturierte Tests", "correct": true, "because": "Abgestufte Phasen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ich hier ohne Integrationstests arbeite?', 2, '[{"text": "Nein", "correct": true, "because": "Integrationstests sind zentral"}, {"text": "Ja", "correct": false, "because": "Alle Ebenen nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Testebene wähle ich, um das Zusammenwirken zu prüfen?', 3, '[{"text": "Integrationstests", "correct": true, "because": "Komponenten verbinden"}, {"text": "Unit-Tests", "correct": false, "because": "Einzelmodule"}, {"text": "Systemtests", "correct": false, "because": "Gesamtsystem"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Testphasen sichern die Qualität?', 5, '[{"text": "Unit-Tests", "correct": true, "because": "Fehler in Modulen finden"}, {"text": "Systemtests", "correct": true, "because": "Gesamtsystem validieren"}, {"text": "Keine Tests", "correct": false, "because": "Qualitätssicherung zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Integrationstests prüfen Verbindungen. b) Systemtests sind unwichtig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Systemtests essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich hier nicht unbedingt?', 4, '[{"text": "Unit-Tests", "correct": false, "because": "Basis der Qualität"}, {"text": "Integrationstests", "correct": false, "because": "Zusammenwirken prüfen"}, {"text": "Spontane Tests", "correct": true, "because": "Strukturierte Ebenen"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Unit-Tests hier unwichtig?', 2, '[{"text": "Nein", "correct": true, "because": "Grundlage der Testphasen"}, {"text": "Ja", "correct": false, "because": "Qualitätssicherung zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Testebenen prüfen das Gesamtsystem?', 4, '[{"text": "Systemtests", "correct": true, "because": "Gesamtfunktion validieren"}, {"text": "Unit-Tests", "correct": false, "because": "Einzelmodule"}, {"text": "Integrationstests", "correct": false, "because": "Teilzusammenwirken"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ich hier ohne Tests arbeite. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Testebenen sind Kern"}, {"text": "Ja", "correct": false, "because": "Qualitätssicherung zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich zuerst bei den Tests?', 3, '[{"text": "Unit-Tests", "correct": true, "because": "Kleinste Einheiten prüfen"}, {"text": "Systemtests", "correct": false, "because": "Spätere Phase"}, {"text": "Keine Tests", "correct": false, "because": "Qualität nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Unit-Tests prüfen Module. b) Integrationstests sind unwichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Integrationstests essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile haben diese Testebenen?', 5, '[{"text": "Frühe Fehlererkennung", "correct": true, "because": "Unit-Tests"}, {"text": "Systemvalidierung", "correct": true, "because": "Systemtests"}, {"text": "Unstrukturierte Prüfung", "correct": false, "because": "Abgestufte Phasen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist hier weniger wichtig?', 3, '[{"text": "Integrationstests", "correct": false, "because": "Zusammenwirken prüfen"}, {"text": "Systemtests", "correct": false, "because": "Gesamtsystem validieren"}, {"text": "Zufällige Prüfungen", "correct": true, "because": "Strukturierte Tests"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Systemtests hier nebensächlich?', 3, '[{"text": "Nein", "correct": true, "because": "Gesamtsystem prüfen"}, {"text": "Ja", "correct": false, "because": "Qualitätssicherung zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ich hier ohne Unit-Tests arbeite?', 2, '[{"text": "Nein", "correct": true, "because": "Unit-Tests sind Basis"}, {"text": "Ja", "correct": false, "because": "Qualitätssicherung zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Testebene wähle ich nach den Unit-Tests?', 4, '[{"text": "Integrationstests", "correct": true, "because": "Zusammenwirken prüfen"}, {"text": "Systemtests", "correct": false, "because": "Spätere Phase"}, {"text": "Keine Tests", "correct": false, "because": "Qualität nötig"}]');
